// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Set;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.MutableBindingSet;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.GraphFrameBindings;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.junit.jupiter.api.Test;

class GraphFrameOriginCompositionTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI GRAPH = VF.createIRI("urn:test:graph-frame");

	@Test
	void lexicalGraphFrameSurvivesProducedOriginViewAndNativeCopies() {
		MapBindingSet raw = new MapBindingSet();
		raw.addBinding("local", VF.createLiteral("value"));
		MutableBindingSet framed = GraphFrameBindings.supply(raw, "graph", GRAPH);
		BindingSet produced = BindingSetOrigin.produced(framed, Set.of("local"));

		assertTrue(GraphFrameBindings.isSupplied(framed, "graph"));
		assertTrue(GraphFrameBindings.isSupplied(produced, "graph"));
		assertTrue(BindingSetOrigin.of(produced).isLocal("local"));
		QueryBindingSet copy = new QueryBindingSet(produced);
		assertTrue(GraphFrameBindings.isSupplied(copy, "graph"));
		assertTrue(BindingSetOrigin.of(copy).isLocal("local"));
		ArrayBindingSet array = new ArrayBindingSet(copy, Set.of("local", "graph"), new String[] { "local", "graph" });
		assertTrue(GraphFrameBindings.isSupplied(array, "graph"));
		assertEquals(BindingSetOrigin.of(produced).key(Set.of("local", "graph")),
				BindingSetOrigin.of(array).key(Set.of("local", "graph")));
		copy.setBinding("graph", VF.createIRI("urn:test:different-graph"));
		assertFalse(GraphFrameBindings.isSupplied(copy, "graph"));
		assertTrue(GraphFrameBindings.isSupplied(produced, "graph"));
	}

	@Test
	void foreignGraphCarrierDoesNotPromoteProducedOriginToRequestAuthority() {
		MapBindingSet raw = new MapBindingSet();
		raw.addBinding("local", VF.createLiteral("value"));
		BindingSet produced = BindingSetOrigin.produced(raw, Set.of("local"));
		MutableBindingSet mutable = BindingSetOrigin.mutable(raw);
		BindingSetOrigin.copy(produced, mutable);
		MutableBindingSet framed = GraphFrameBindings.supply(mutable, "graph", GRAPH);

		assertTrue(BindingSetOrigin.of(framed).isLocal("local"));
		assertSame(framed, BindingSetOrigin.requestInput(framed));
		assertFalse(BindingSetOrigin.of(BindingSetOrigin.requestInput(framed)).isRequest("local"));
		QueryBindingSet copy = new QueryBindingSet(framed);
		assertTrue(BindingSetOrigin.of(copy).isLocal("local"));
		assertTrue(GraphFrameBindings.isSupplied(copy, "graph"));
	}

	@Test
	void namesAndEqualRdfTermsDoNotCreateLexicalGraphAuthority() {
		MapBindingSet raw = new MapBindingSet();
		raw.addBinding("graph", GRAPH);
		assertFalse(GraphFrameBindings.isSupplied(raw, "graph"));
		assertFalse(GraphFrameBindings.isSupplied(new QueryBindingSet(raw), "graph"));
		assertFalse(BindingSetOrigin.of(raw).isRequest("graph"));
		assertFalse(BindingSetOrigin.of(raw).isLocal("graph"));
	}
}
